import React from 'react';

function Header() {
  return (
    <header className="bg-gray-800 p-4 shadow-lg sticky top-0 z-50">
      <nav className="container mx-auto flex justify-between items-center">
        <div className="text-2xl font-bold text-white">Manoj Kumar R</div>
        <ul className="flex space-x-6">
          <li><a href="#home" className="text-gray-300 hover:text-white transition duration-300">Home</a></li>
          <li><a href="#about" className="text-gray-300 hover:text-white transition duration-300">About</a></li>
          <li><a href="#projects" className="text-gray-300 hover:text-white transition duration-300">Projects</a></li>
          <li><a href="#skills" className="text-gray-300 hover:text-white transition duration-300">Skills</a></li>
          <li><a href="#experience" className="text-gray-300 hover:text-white transition duration-300">Experience</a></li>
          <li><a href="#contact" className="text-gray-300 hover:text-white transition duration-300">Contact</a></li>
        </ul>
      </nav>
    </header>
  );
}

export default Header;
